def adjoin(a: int, b: int) -> int:
    return b | (1 << a)

def pairing(a: int, b: int) -> int:
    return adjoin(a, adjoin(b, 0))

def bin_union(a: int, b: int) -> int:
    return a | b

def is_subset(x: int, a: int) -> bool:
    return (x & a) == x

def power_set(a: int) -> int:
    p = 0
    for x in range(a + 1):
        if is_subset(x, a):
            p |= (1 << x)
    return p

if __name__ == "__main__":
