def mem(a: int, b: int) -> bool:
    return (b >> a) & 1 == 1

def succ(a: int) -> int:
    return a | (1 << a)

def numeral(n: int) -> int:
    x = 0
    for _ in range(n):
        x = succ(x)
    return x

def is_inductive(I: int) -> bool:
    if not mem(0, I):
        return False
    return all(mem(succ(x), I) for x in range(I.bit_length()) if mem(x, I))

if __name__ == "__main__":
    print("numerals:", [numeral(n) for n in range(5)])
    print("n <= numeral(n):", all(n <= numeral(n) for n in range(5)))
    print("inductive sets below 5000:", [I for I in range(5000) if is_inductive(I)])

