from typing import Any, List

def members(b: int) -> List[int]:
    """Positions of the 1-bits of b: the direct members of the coded set."""
    return [a for a in range(b.bit_length()) if (b >> a) & 1 == 1]

def decode(b: int) -> Any:
    """Fully decode b into a nested Python frozenset (a hereditarily finite set)."""
    return frozenset(decode(a) for a in members(b))

def decode_str(b: int) -> str:
    """Human-readable braces rendering of the set coded by b."""
    return "{" + ", ".join(decode_str(a) for a in members(b)) + "}"

