from typing import Callable, List, Set

def is_well_founded(carrier: List[int], mem: Callable[[int, int], bool]) -> bool:
    """Peel off in-minimal elements; leftovers witness non-well-foundedness."""
    remaining: Set[int] = set(carrier)
    while remaining:
        minimal = {y for y in remaining
                   if not any(mem(x, y) for x in remaining)}
        if not minimal:
            return False           # a cycle / regress survives (e.g. a Quine atom)
        remaining -= minimal
    return True

