import matplotlib.pyplot as plt

def mem(a: int, b: int) -> bool:
    return (b >> a) & 1 == 1

def main(N: int = 16) -> None:
    fig, ax = plt.subplots(figsize=(9, 6))
    pos = {b: (b, bin(b).count("1")) for b in range(N)}
    for b in range(N):
        for a in range(b):
            if mem(a, b):
                (x0, y0), (x1, y1) = pos[a], pos[b]
                ax.annotate("", xy=(x1, y1), xytext=(x0, y0),
                            arrowprops=dict(arrowstyle="->", color="#4477aa", alpha=0.6))
    for b, (x, y) in pos.items():
        ax.scatter([x], [y], s=420, color="#ffd24d", edgecolors="black", zorder=3)
        ax.text(x, y, str(b), ha="center", va="center", zorder=4)
    ax.set_xlabel("Ackermann code"); ax.set_ylabel("rank (popcount)")
    ax.set_title("Membership digraph of the finite Ackermann universe")
    plt.tight_layout(); plt.savefig("membership_digraph.png", dpi=150)

if __name__ == "__main__":
    main()
